package com.opensocket.aievent.core.iam.persistence.repository;
import static com.opensocket.aievent.core.iam.persistence.repository.RowValues.*;import com.opensocket.aievent.core.iam.authentication.application.port.out.*;import com.opensocket.aievent.core.iam.authentication.domain.*;import com.opensocket.aievent.core.iam.persistence.dao.IamAuthenticationDao;import com.opensocket.aievent.core.iam.persistence.exception.IamOptimisticLockException;import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;import java.time.*;import java.util.*;
@DatabaseRepositoryAdapter public class MybatisPasswordAuthenticationRepository implements PasswordCredentialRepository,PasswordHistoryRepository,PasswordPolicyRepository{private final IamAuthenticationDao dao;public MybatisPasswordAuthenticationRepository(IamAuthenticationDao dao){this.dao=dao;}public Optional<PasswordCredential>find(CredentialSubjectType type,String id){return Optional.ofNullable(dao.findCredential(type.name(),id)).map(this::credential);}public PasswordCredential save(PasswordCredential c,long expected){int n=expected==0?dao.insertCredential(credentialRow(c)):dao.updateCredential(credentialRow(c),expected);if(n!=1)throw new IamOptimisticLockException("PasswordCredential",c.subjectId(),expected);return c;}public List<PasswordHistoryEntry>findRecent(CredentialSubjectType type,String id,int limit){if(limit<=0)return List.of();return dao.findPasswordHistory(type.name(),id,limit).stream().map(this::history).toList();}public void append(PasswordHistoryEntry e){dao.insertPasswordHistory(historyRow(e));}public void trim(CredentialSubjectType type,String id,int keep){dao.trimPasswordHistory(type.name(),id,Math.max(keep,0));}public PasswordPolicy instanceMinimum(){Map<String,Object>r=dao.findInstancePasswordPolicy();return r==null?PasswordPolicy.secureDefault():policy(r);}public Optional<PasswordPolicy>findTenantPolicy(String tenantId){return Optional.ofNullable(dao.findTenantPasswordPolicy(tenantId)).map(this::policy);}public PasswordPolicy saveTenantPolicy(String tenantId,PasswordPolicy p,String actor,long expected){Map<String,Object>r=policyRow(tenantId,p,actor,expected==0?1:expected+1);int n=expected==0?dao.insertTenantPasswordPolicy(r):dao.updateTenantPasswordPolicy(r,expected);if(n!=1)throw new IamOptimisticLockException("TenantPasswordPolicy",tenantId,expected);return p;}private PasswordCredential credential(Map<String,Object>r){return PasswordCredential.reconstitute(CredentialSubjectType.valueOf(string(r,"subjectType")),string(r,"subjectId"),new PasswordHash(string(r,"hashAlgorithm"),string(r,"passwordHash")),instant(r,"changedAt"),instant(r,"expiresAt"),bool(r,"mustChange"),longValue(r,"version"));}private PasswordHistoryEntry history(Map<String,Object>r){return new PasswordHistoryEntry(string(r,"historyId"),CredentialSubjectType.valueOf(string(r,"subjectType")),string(r,"subjectId"),new PasswordHash(string(r,"hashAlgorithm"),string(r,"passwordHash")),instant(r,"changedAt"));}private PasswordPolicy policy(Map<String,Object>r){return new PasswordPolicy(intValue(r,"minimumLength"),intValue(r,"maximumLength"),bool(r,"requireUppercase"),bool(r,"requireLowercase"),bool(r,"requireNumber"),bool(r,"requireSymbol"),intValue(r,"passwordHistoryCount"),Duration.ofSeconds(longValue(r,"maximumAgeSeconds")),Duration.ofSeconds(longValue(r,"minimumAgeSeconds")),intValue(r,"failedAttemptThreshold"),Duration.ofSeconds(longValue(r,"lockoutDurationSeconds")),PasswordPolicy.BreachedPasswordMode.valueOf(string(r,"breachedPasswordMode")));}private Map<String,Object>credentialRow(PasswordCredential c){Map<String,Object>m=new HashMap<>();m.put("subjectType",c.subjectType().name());m.put("subjectId",c.subjectId());m.put("hashAlgorithm",c.passwordHash().algorithm());m.put("passwordHash",c.passwordHash().encoded());m.put("changedAt",c.changedAt());m.put("expiresAt",c.expiresAt());m.put("mustChange",c.mustChange());m.put("version",c.version());return m;}private Map<String,Object>historyRow(PasswordHistoryEntry e){Map<String,Object>m=new HashMap<>();m.put("historyId",e.historyId());m.put("subjectType",e.subjectType().name());m.put("subjectId",e.subjectId());m.put("hashAlgorithm",e.passwordHash().algorithm());m.put("passwordHash",e.passwordHash().encoded());m.put("changedAt",e.changedAt());return m;}private Map<String,Object>policyRow(String tenant,PasswordPolicy p,String actor,long version){Map<String,Object>m=new HashMap<>();m.put("tenantId",tenant);m.put("minimumLength",p.minimumLength());m.put("maximumLength",p.maximumLength());m.put("requireUppercase",p.requireUppercase());m.put("requireLowercase",p.requireLowercase());m.put("requireNumber",p.requireNumber());m.put("requireSymbol",p.requireSymbol());m.put("passwordHistoryCount",p.passwordHistoryCount());m.put("maximumAgeSeconds",p.maximumAge().toSeconds());m.put("minimumAgeSeconds",p.minimumAge().toSeconds());m.put("failedAttemptThreshold",p.failedAttemptThreshold());m.put("lockoutDurationSeconds",p.lockoutDuration().toSeconds());m.put("breachedPasswordMode",p.breachedPasswordMode().name());m.put("updatedAt",Instant.now());m.put("updatedBy",actor);m.put("version",version);return m;}}
